// Synthetic GraphQL resolvers. Every name is invented; held-place-graphql.test.ts
// wraps the returned values below.

type OrderShape = { id: string; total: number };

declare function loadOrder(id: string): Promise<OrderShape>;
declare const payload: any;

export const orderResolvers = {
  async order(_p: unknown, args: { id: string }) {
    return __C.send0_0(loadOrder(args.id), (o) => o);
  },
  orders() {
    return __C.send1_0({ edges: [{ id: "1", total: 2 }], totalCount: 1 }, (o) => o);
  },
  archived() {
    return null;
  },
  paid() {
    return true;
  },
  raw() {
    return payload;
  },
};

declare namespace __C {
  type __carrick_Sent<S, E> = S;
  type __carrick_GqlExpected<E> = E;
  type __carrick_GqlSent<S, E> = S;
  type __carrick_GqlSentS<S, E, R> = S;
  type O0_0 = ({ id: string }) & { readonly __carrick_never: true };
  function send0_0<V>(v: V, c: (o: __carrick_GqlSent<Awaited<V>, O0_0>) => __carrick_GqlExpected<O0_0>): V;
  type O1_0 = ({ totalCount: number }) & { readonly __carrick_never: true };
  type L1_0 = {"type":"Orders"};
  function send1_0<V>(v: V, c: (o: __carrick_GqlSentS<Awaited<V>, O1_0, L1_0>) => __carrick_GqlExpected<O1_0>): V;
}
